import { google, sheets_v4 } from "googleapis";

export const RESERVATION_SHEET_NAMES = ["国内", "韓国", "台湾"] as const;
export type ReservationSheetName = typeof RESERVATION_SHEET_NAMES[number];

export type ReservationRecord = {
  sheetName: ReservationSheetName;
  rowNumber: number;
  values: Record<string, string>;
};

let cachedSheetsClient: sheets_v4.Sheets | null = null;

async function getSheetsClient(): Promise<sheets_v4.Sheets> {
  if (cachedSheetsClient) {
    return cachedSheetsClient;
  }
  const email = process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
  const key = process.env.GOOGLE_SERVICE_ACCOUNT_KEY?.replace(/\\n/g, "\n");
  if (!email || !key) {
    throw new Error("Google service account credentials are not set in environment variables.");
  }
  const auth = new google.auth.JWT({
    email,
    key,
    scopes: ["https://www.googleapis.com/auth/spreadsheets"],
  });
  cachedSheetsClient = google.sheets({ version: "v4", auth });
  return cachedSheetsClient;
}

async function getHeaderRow(sheetName: ReservationSheetName): Promise<string[]> {
  const sheets = await getSheetsClient();
  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  const response = await sheets.spreadsheets.values.get({
    spreadsheetId,
    range: `${sheetName}!1:1`,
  });
  const rows = response.data.values;
  if (!rows || rows.length === 0) {
    return [];
  }
  return rows[0].map((cell) => String(cell ?? ""));
}

function columnIndexToA1(index: number): string {
  let temp = index + 1;
  let letter = "";
  while (temp > 0) {
    const remainder = (temp - 1) % 26;
    letter = String.fromCharCode(65 + remainder) + letter;
    temp = Math.floor((temp - 1) / 26);
  }
  return letter;
}

async function ensureStatusColumns(sheetName: ReservationSheetName): Promise<void> {
  const sheets = await getSheetsClient();
  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  const headers = await getHeaderRow(sheetName);
  const required = ["ステータス", "確定日時", "Meetリンク"];
  const missing = required.filter((col) => !headers.includes(col));
  if (missing.length === 0) {
    return;
  }
  const newHeaders = [...headers, ...missing];
  const startCol = columnIndexToA1(0);
  const endCol = columnIndexToA1(newHeaders.length - 1);
  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range: `${sheetName}!${startCol}1:${endCol}1`,
    valueInputOption: "USER_ENTERED",
    requestBody: {
      values: [newHeaders],
    },
  });
}

export async function listPendingReservations(): Promise<ReservationRecord[]> {
  const sheets = await getSheetsClient();
  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  const results: ReservationRecord[] = [];

  for (const sheetName of RESERVATION_SHEET_NAMES) {
    await ensureStatusColumns(sheetName);
    const response = await sheets.spreadsheets.values.get({
      spreadsheetId,
      range: sheetName,
    });
    const rows = response.data.values;
    if (!rows || rows.length <= 1) {
      continue;
    }
    const headers = rows[0].map((cell) => String(cell ?? ""));
    const statusIndex = headers.indexOf("ステータス");

    for (let i = 1; i < rows.length; i++) {
      const rowNumber = i + 1;
      const row = rows[i] || [];
      const statusValue = statusIndex >= 0 ? String(row[statusIndex] ?? "").trim() : "";

      if (statusValue === "" || statusValue === "未確定") {
        const values: Record<string, string> = {};
        for (let j = 0; j < headers.length; j++) {
          const headerName = headers[j];
          if (headerName) {
            values[headerName] = String(row[j] ?? "");
          }
        }
        results.push({
          sheetName,
          rowNumber,
          values,
        });
      }
    }
  }

  return results;
}

export async function confirmReservation(
  sheetName: ReservationSheetName,
  rowNumber: number,
  confirmedDateTime: string,
  meetLink: string
): Promise<void> {
  const sheets = await getSheetsClient();
  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  await ensureStatusColumns(sheetName);
  const headers = await getHeaderRow(sheetName);
  const statusIndex = headers.indexOf("ステータス");
  const confirmedDateTimeIndex = headers.indexOf("確定日時");
  const meetLinkIndex = headers.indexOf("Meetリンク");

  if (statusIndex < 0 || confirmedDateTimeIndex < 0 || meetLinkIndex < 0) {
    throw new Error("Required status columns not found in sheet header.");
  }

  const startCol = columnIndexToA1(Math.min(statusIndex, confirmedDateTimeIndex, meetLinkIndex));
  const endCol = columnIndexToA1(Math.max(statusIndex, confirmedDateTimeIndex, meetLinkIndex));

  // Build row values for update range or update individually/batch range
  // To be safe and precise, fetch the exact row or update specific columns range
  const range = `${sheetName}!${startCol}${rowNumber}:${endCol}${rowNumber}`;

  // Alternatively, fetch the row first or update columns relative to sheet
  // Actually, spreadsheets.values.update requires array of values for the range.
  // If indices are not contiguous, updating separate ranges or fetching the row range (min to max index) is safer.
  const minIdx = Math.min(statusIndex, confirmedDateTimeIndex, meetLinkIndex);
  const maxIdx = Math.max(statusIndex, confirmedDateTimeIndex, meetLinkIndex);
  const rowRange = `${sheetName}!${columnIndexToA1(minIdx)}${rowNumber}:${columnIndexToA1(maxIdx)}${rowNumber}`;

  const rowResp = await sheets.spreadsheets.values.get({
    spreadsheetId,
    range: rowRange,
  });
  const rowValues = (rowResp.data.values && rowResp.data.values[0]) ? [...rowResp.data.values[0]] : [];

  // Pad rowValues if needed
  while (rowValues.length <= maxIdx - minIdx) {
    rowValues.push("");
  }

  rowValues[statusIndex - minIdx] = "確定";
  rowValues[confirmedDateTimeIndex - minIdx] = confirmedDateTime;
  rowValues[meetLinkIndex - minIdx] = meetLink;

  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range: rowRange,
    valueInputOption: "USER_ENTERED",
    requestBody: {
      values: [rowValues],
    },
  });
}

export async function cancelReservation(
  sheetName: ReservationSheetName,
  rowNumber: number
): Promise<void> {
  const sheets = await getSheetsClient();
  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  await ensureStatusColumns(sheetName);
  const headers = await getHeaderRow(sheetName);
  const statusIndex = headers.indexOf("ステータス");
  if (statusIndex < 0) {
    throw new Error("Status column not found in sheet header.");
  }

  const colLetter = columnIndexToA1(statusIndex);
  const range = `${sheetName}!${colLetter}${rowNumber}`;

  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range,
    valueInputOption: "USER_ENTERED",
    requestBody: {
      values: [["キャンセル"]],
    },
  });
}
